import{state,ENVS,clamp}from'./state.js';
import{toggleAudio,stopAudio}from'./audio.js';
import{ui,toast,requestTilt,startOrientation,bindSettings,updateControlUI,updateStartCopy,updateHud}from'./ui.js';
function bindSteer(btn,dir){const down=e=>{e.preventDefault();state.buttonSteer=dir},up=e=>{e.preventDefault();if(state.buttonSteer===dir)state.buttonSteer=0};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)}
const resetDynamics=()=>Object.assign(state,{cameraYaw:0,cameraRoll:0,cameraBob:0,carYaw:0,roadYaw:0,suspensionKick:0,speedPulse:0});
export function initControls(){bindSettings();ui.startBtn.addEventListener('click',async()=>{ui.permissionNote.textContent='';if(state.control==='tilt'&&!(await requestTilt())){state.control='buttons';updateControlUI();ui.permissionNote.textContent='傾きセンサーを使えないため、ボタン操作で開始します。';toast('傾き操作を使えないためボタン操作に切替')}state.endless=ui.endlessToggle.checked;Object.assign(state,{running:true,paused:false,speed:18,distance:0,roadPhase:0,lateral:0,steer:0,buttonSteer:0,tiltSteer:0,tiltZero:null,feature:null,featureProgress:0,featureCooldown:14});resetDynamics();state.envIndex=Math.max(0,ENVS.indexOf(state.environment));state.routeOrigin=state.envIndex;ui.startScreen.classList.add('is-hidden');ui.hud.classList.remove('is-hidden');ui.pauseOverlay.classList.add('is-hidden');updateControlUI();updateHud();state.lastT=performance.now()});ui.pauseBtn.addEventListener('click',()=>{state.paused=true;ui.pauseOverlay.classList.remove('is-hidden')});ui.resumeBtn.addEventListener('click',()=>{state.paused=false;ui.pauseOverlay.classList.add('is-hidden');state.lastT=performance.now()});ui.backToMenuBtn.addEventListener('click',()=>{state.running=false;state.paused=false;stopAudio(ui.soundBtn);ui.pauseOverlay.classList.add('is-hidden');ui.hud.classList.add('is-hidden');ui.startScreen.classList.remove('is-hidden')});ui.resetBtn.addEventListener('click',()=>{Object.assign(state,{distance:0,roadPhase:0,lateral:0,tiltZero:null,feature:null,featureProgress:0,featureCooldown:10,speed:24});resetDynamics();toast('ドライブをリセットしました')});ui.recenterBtn.addEventListener('click',()=>{state.tiltZero=null;state.lateral*=.3;toast('傾きの中心を再設定')});ui.controlToggleBtn.addEventListener('click',async()=>{if(state.control==='tilt')state.control='buttons';else{const ok=await requestTilt();state.control=ok?'tilt':'buttons';if(!ok)toast('傾きセンサーを利用できません');state.tiltZero=null}updateControlUI()});ui.speedDownBtn.addEventListener('click',()=>state.targetSpeed=clamp(state.targetSpeed-12,34,138));ui.speedUpBtn.addEventListener('click',()=>state.targetSpeed=clamp(state.targetSpeed+12,34,138));ui.soundBtn.addEventListener('click',()=>toggleAudio(ui.soundBtn));bindSteer(ui.leftBtn,-1);bindSteer(ui.rightBtn,1);startOrientation();updateStartCopy();updateControlUI()}
